const i={yingshe:{bibi:"현물",bibidingdan:"현물 주문",bibijiaoyi:"현물 거래",jiamihuobi:"무기한 계약",miaoheyue:"결제 계약",miaoheyuejiaoyi:"결제 계약 거래"},jiaoyi:{xianhuomingcheng:"현물 명칭"},aurexion:{jianguanwenjian:"규제 문서"},rwa_283:{jiaru:"지금 RWA 가입하기",biaoti:"초저수수료, 탁월한 보안, 높은 거래 한도 및 최고 수준의 지원",xiazai:"앱 다운로드",jiaoyiliang:"24시간 거래량",guanyu:"RWA 소개",guanyuxiangqing:"RWA는 투자, 자문 및 리스크 관리 솔루션을 제공하는 세계적인 선도 기업 중 하나입니다. 우리는 고객에 대한 신탁 책임을 다합니다. 고객의 미래 투자를 지원하고, 직원들에게 영감을 주며, 지역 사회를 지원합니다. 자세한 내용은 영상을 확인하세요.",jieshao:"포춘 매거진 선정 세계에서 가장 존경받는 기업",jieshaoxiangqing:"RWA는 12년 연속 포춘 매거진의 ‘세계에서 가장 존경받는 기업’ 목록에 선정되었으며, 증권 및 자산운용 업계에서 1위를 차지했습니다.",weishenme:"왜 RWA를 선택해야 할까요?",weishenmexiangqing:"점점 더 많은 투자자들이 RWA를 신뢰하고 있으며, 이는 업계 어느 기업보다도 다양한 선택지를 제공하기 때문입니다. 우리의 글로벌 플랫폼은 고객이 가장 중요한 재무 목표를 달성하도록 설계되었습니다.",weishenmexiangqing1:"지난 5년간 순유입 자금 1조 8천억 달러",weishenmexiangqing2:"3,500만 명 이상의 미국인의 투자 및 은퇴 저축 지원",weishenmexiangqing3:"미국 내 19만 명 이상의 금융 자문가가 RWA를 선택",huoban:"파트너",huobanxiangqing:"최근 몇 년간 RWA는 인공지능(AI) 분야에 적극적으로 투자하며, 인프라, 칩 기술, 데이터 분석 및 지속 가능한 발전 분야에서 여러 AI 기업과 파트너십을 구축해 왔습니다.",huoban1:"글로벌 AI 인프라 투자 파트너십(AIP)",huoban11:"2024년 9월, RWA는 Microsoft, Mubadala, GIP와 함께 글로벌 AI 인프라 투자 파트너십(AIP)을 출범시켰으며, 300억 달러 이상의 인프라 투자를 목표로 하고 있습니다.",huoban2:"AI 칩 스타트업 Groq 투자",huoban22:"2024년 8월, RWA는 Groq의 6억 4천만 달러 규모 투자 라운드를 주도하여 기업 가치를 28억 달러로 끌어올렸습니다.",huoban3:"AI 분석 기업 Pyramid Analytics 투자",huoban33:"2024년 11월, RWA는 AI 기반 비즈니스 분석 기업 Pyramid Analytics에 5천만 달러를 투자했습니다.",huoban4:"Clarity AI와의 전략적 파트너십",huoban44:"2021년부터 RWA는 지속 가능성 평가 플랫폼 Clarity AI에 투자하고, 해당 기능을 투자 관리 플랫폼 Aladdin에 통합해 왔습니다.",huoban5:"이러한 협력을 통해 RWA는 AI 인프라와 칩 기술에 대한 투자를 가속화하고, 데이터 분석 및 지속 가능성 분야에서의 전략적 입지를 강화하고 있습니다.",chongti:"빠른 입출금",chongtixiangqing:"여러 일반적인 결제 수단을 지원하여 빠른 입출금 가능",huanying:"RWA 서비스에 오신 것을 환영합니다",baipishu:"백서",chengyuandengjice:"회원 명부",gongsizhangcheng:"정관",gupiaozhengshu:"주식 증서",huiyijilu:"회의록",zhucezhengshu:"등록 증명서",shuihao:"납세자 번호",weijiaoyiersheng:"트레이딩을 위해 태어나다",guanlianzhanghu:"연결된 계정",yizhixingdingdan:"체결된 주문",xinwen:"뉴스",cishan:"자선",efepeishou:"ETF 배정",rineijiaoyi:"일중 거래"}};export{i as default};
